<script setup lang="ts">
import type { PerformanceLevel } from '@englishflow/performance'
const qualityLabels: Record<PerformanceLevel, string> = { Ultra: '极致', High: '高清', Medium: '标准', Performance: '省电' }
function qualityLabel(level: PerformanceLevel): string { return qualityLabels[level] ?? level }
withDefaults(defineProps<{ status: 'idle' | 'loading' | 'ready' | 'empty' | 'offline' | 'error'; message?: string | null; queueCount?: number; performanceLevel?: PerformanceLevel }>(), { message: null, queueCount: 0, performanceLevel: 'High' })
const emit = defineEmits<{ retry: []; sync: []; performance: [level: PerformanceLevel] }>()
</script>
<template><view class="status-panel" :class="`status-panel--${status}`" role="status"><view class="status-panel__copy"><text class="status-panel__title">{{ status === 'loading' ? '正在读取服务端数据' : status === 'empty' ? '当前没有可用内容' : status === 'offline' ? '网络暂时不可用' : status === 'error' ? '服务端暂时不可用' : '服务状态' }}</text><text class="status-panel__message">{{ message ?? (status === 'offline' ? '断点和待同步事件仍保留；待同步不等于已掌握。' : status === 'empty' ? '没有使用本地样例填充页面。' : '掌握与判分以服务端结果为准。') }}</text></view><view class="status-panel__actions"><text v-if="queueCount" class="status-panel__queue">待同步 {{ queueCount }}</text><button tabindex="0" role="button" v-if="status === 'offline' || status === 'error'" class="mini-button" type="button" @click="emit('retry')">重试</button><button tabindex="0" role="button" v-if="queueCount" class="mini-button" type="button" @click="emit('sync')">同步</button><picker :range="[qualityLabel('Ultra'), qualityLabel('High'), qualityLabel('Medium'), qualityLabel('Performance')]" :value="['Ultra', 'High', 'Medium', 'Performance'].indexOf(performanceLevel)" @change="emit('performance', ['Ultra', 'High', 'Medium', 'Performance'][$event.detail.value] as PerformanceLevel)"><view class="quality-picker">{{ qualityLabel(performanceLevel) }}</view></picker></view></view></template>
<style scoped lang="scss">.status-panel{display:flex;align-items:center;justify-content:space-between;gap:16rpx;padding:24rpx;border:1rpx solid var(--yx-border);border-radius:18rpx;background:var(--yx-surface-card)}.status-panel--offline,.status-panel--error{border-color:var(--yx-danger);background:var(--yx-surface-page)}.status-panel__copy{display:grid;gap:8rpx;flex:1}.status-panel__title{font-size:28rpx;font-weight:700}.status-panel__message{color:var(--yx-text-secondary);font-size:23rpx;line-height:1.5}.status-panel__actions{display:flex;align-items:center;gap:10rpx;flex-wrap:wrap;justify-content:flex-end}.status-panel__queue{color:var(--yx-warning);font-size:21rpx;font-weight:700}.mini-button,.quality-picker{min-height:64rpx;padding:0 18rpx;border:1rpx solid var(--yx-border);border-radius:12rpx;color:var(--yx-brand);background:var(--yx-surface-card);font-size:22rpx;line-height:64rpx}.quality-picker{color:var(--yx-text-secondary)}@media(max-width:620px){.status-panel{display:grid}.status-panel__actions{justify-content:flex-start}}</style>
